  (void)has;
  Trace t;
  State s = {c.x0, c.v0, c.th0, c.w0};
  Rng rng(sc.seed);
  double work = 0, u_applied = 0;
  auto record = [&](int sub) {
    StepRecord r;
    r.body.push_back({s.x, s.th, s.v, s.w});
    r.energy = cartpole_energy(c, r.body[0]);
    r.work = work;
    r.fmag = std::fabs(u_applied);
