  const int nsub = std::max(1, static_cast<int>(std::ceil(sc.dt / 0.005 - 1e-9)));
  const double h = sc.dt / nsub;
  const Gains K = design_gains(c);
  for (int k = 1; k <= sc.steps; ++k) {
