    double th_meas = s.th + (c.noise > 0 ? rng.range(-c.noise, c.noise) : 0.0);
    double w_meas = s.w;
    double u = K.kx * s.x + K.kv * s.v + K.kth * th_meas + K.kw * w_meas;
    double lim = c.fmax;
    u = std::max(-lim, std::min(lim, u));
    u_applied = u;
